import sys

def min_operations_to_portal(grid, n, m):
    # We need to find a sub-rectangle of size a x b (a >= 5, b >= 4)
    # and calculate the minimum number of operations needed to make it a portal.
    # We'll check all possible a x b rectangles where a ranges from 5 to n, and b from 4 to m.

    min_ops = float('inf')

    for a in range(5, n + 1):
        for b in range(4, m + 1):
            # Try all possible top-left positions (i, j) such that i + a <= n and j + b <= m
            for i in range(n - a + 1):
                for j in range(m - b + 1):
                    # Calculate the number of operations needed to make this rectangle a portal
                    # The four borders (top, bottom, left, right) must be all 1s, except the corners
                    # The inner area must be all 0s
                    ops = 0
                    # Top and bottom rows
                    for x in range(i, i + a):
                        for y in range(j, j + b):
                            if x == i or x == i + a - 1:
                                if y == j or y == j + b - 1:
                                    # Corners can be anything
                                    continue
                                if grid[x][y] == '0':
                                    ops += 1
                            elif y == j or y == j + b - 1:
                                if grid[x][y] == '0':
                                    ops += 1
                            else:
                                if grid[x][y] == '1':
                                    ops += 1
                    # Update the minimum operations
                    min_ops = min(min_ops, ops)
    return min_ops

