import sys
import math

def count_polycarp_numbers(n):
    # Count squares
    squares = int(math.isqrt(n))
    # Count cubes
    cubes = int(n ** (1/3))
    # Adjust cubes for precision (since cube root can be slightly off due to floating point)
    # We can use binary search or a better method to count cubes accurately
    # Here we use a binary search approach for better precision
    def count_cubes(n):
        low, high = 1, n
        while low <= high:
            mid = (low + high) // 2
            cube = mid ** 3
            if cube == n:
                return mid
            elif cube < n:
                low = mid + 1
            else:
                high = mid - 1
        return 0  # No cube found

    # But for efficiency, we can use the cube root and adjust
    # We can use math.isqrt for integer square roots and similar for cube roots
    # For cube roots, we can use binary search to get the exact count
    # So we'll calculate cubes correctly with binary search
    def count_cubes(n):
        low, high = 1, n
        while low <= high:
            mid = (low + high) // 2
            cube = mid ** 3
            if cube == n:
                return mid
            elif cube < n:
                low = mid + 1
            else:
                high = mid - 1
        return 0

    cubes = 0
    for i in range(1, n + 1):
        if i ** 3 <= n:
            cubes += 1
        else:
            break

    # Count 6th powers (numbers that are both squares and cubes)
    sixth_powers = int(math.isqrt(n))
    # But for accuracy, we should use binary search again
    def count_sixth_powers(n):
        low, high = 1, n
        while low <= high:
            mid = (low + high) // 2
            sixth = mid ** 6
            if sixth == n:
                return mid
            elif sixth < n:
                low = mid + 1
            else:
                high = mid - 1
        return 0

    sixth_powers = 0
    for i in range(1, n + 1):
        if i ** 6 <= n:
            sixth_powers += 1
        else:
            break

    return squares + cubes - sixth_powers

def main():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        print(count_polycarp_numbers(n))

if __name__ == "__main__":
    main()
